xpath.attribute:
card #{
                (tx_sudo.state == 'pending' and 'bg-info') or
                (tx_sudo.state == 'done' and order.currency_id.compare_amounts(lm_checkout_total, tx_sudo.amount) == 0 and 'alert-success') or
                (tx_sudo.state == 'done' and 'bg-warning') or
                (tx_sudo.state == 'authorized' and 'alert-success') or
                'bg-danger'}
